USE jac_tpcc_graph;
CREATE OR REPLACE VIEW warehouse AS SELECT CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.w_id')) AS SIGNED) AS w_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.w_ytd')) AS DECIMAL(20,2)) AS w_ytd FROM anchors a  WHERE a.arch_type='Warehouse' AND a.kind='NodeAnchor';
CREATE OR REPLACE VIEW district AS SELECT 1 AS d_w_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.d_id')) AS SIGNED) AS d_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.d_ytd')) AS DECIMAL(20,2)) AS d_ytd,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.d_next_o_id')) AS SIGNED) AS d_next_o_id FROM anchors a  WHERE a.arch_type='District' AND a.kind='NodeAnchor';
CREATE OR REPLACE VIEW customer AS SELECT 1 AS c_w_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(d.props,'$.archetype.d_id')) AS SIGNED) AS c_d_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.c_id')) AS SIGNED) AS c_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.c_balance')) AS DECIMAL(20,2)) AS c_balance,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.c_ytd_payment')) AS DECIMAL(20,2)) AS c_ytd_payment,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.c_payment_cnt')) AS SIGNED) AS c_payment_cnt,JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.c_data')) AS c_data FROM anchors a JOIN anchors e ON e.dst=a.id AND e.arch_type='GenericEdge' AND e.kind='EdgeAnchor' JOIN anchors d ON d.id=e.src AND d.arch_type='District' WHERE a.arch_type='Customer' AND a.kind='NodeAnchor';
CREATE OR REPLACE VIEW stock AS SELECT 1 AS s_w_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.s_i_id')) AS SIGNED) AS s_i_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.s_quantity')) AS SIGNED) AS s_quantity,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.s_ytd')) AS SIGNED) AS s_ytd,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.s_order_cnt')) AS SIGNED) AS s_order_cnt,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.s_remote_cnt')) AS SIGNED) AS s_remote_cnt FROM anchors a  WHERE a.arch_type='Stock' AND a.kind='NodeAnchor';
CREATE OR REPLACE VIEW orders AS SELECT 1 AS o_w_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.o_d_id')) AS SIGNED) AS o_d_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.o_id')) AS SIGNED) AS o_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.o_c_id')) AS SIGNED) AS o_c_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.o_carrier_id')) AS SIGNED) AS o_carrier_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.o_ol_cnt')) AS SIGNED) AS o_ol_cnt,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.o_all_local')) AS SIGNED) AS o_all_local FROM anchors a  WHERE a.arch_type='Order' AND a.kind='NodeAnchor';
CREATE OR REPLACE VIEW new_order AS SELECT 1 AS no_w_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.o_d_id')) AS SIGNED) AS no_d_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.o_id')) AS SIGNED) AS no_o_id FROM anchors a  WHERE a.arch_type='Order' AND a.kind='NodeAnchor' AND JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.new_order'))='true';
CREATE OR REPLACE VIEW order_line AS SELECT 1 AS ol_w_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(p.props,'$.archetype.o_d_id')) AS SIGNED) AS ol_d_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(p.props,'$.archetype.o_id')) AS SIGNED) AS ol_o_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.ol_number')) AS SIGNED) AS ol_number,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.ol_i_id')) AS SIGNED) AS ol_i_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.ol_supply_w_id')) AS SIGNED) AS ol_supply_w_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.ol_quantity')) AS SIGNED) AS ol_quantity,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.ol_amount')) AS DECIMAL(20,2)) AS ol_amount,JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.ol_dist_info')) AS ol_dist_info FROM anchors a JOIN anchors e ON e.dst=a.id AND e.kind='EdgeAnchor' AND e.arch_type='GenericEdge' JOIN anchors p ON p.id=e.src AND p.arch_type='Order' WHERE a.arch_type='OrderLine' AND a.kind='NodeAnchor';
CREATE OR REPLACE VIEW history AS SELECT 1 AS h_c_w_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(d.props,'$.archetype.d_id')) AS SIGNED) AS h_c_d_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(c.props,'$.archetype.c_id')) AS SIGNED) AS h_c_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.h_w_id')) AS SIGNED) AS h_w_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.h_d_id')) AS SIGNED) AS h_d_id,CAST(JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.h_amount')) AS DECIMAL(20,2)) AS h_amount,JSON_UNQUOTE(JSON_EXTRACT(a.props,'$.archetype.h_data')) AS h_data FROM anchors a JOIN anchors e ON e.dst=a.id AND e.kind='EdgeAnchor' AND e.arch_type='GenericEdge' JOIN anchors c ON c.id=e.src AND c.arch_type='Customer' JOIN anchors ce ON ce.dst=c.id AND ce.kind='EdgeAnchor' AND ce.arch_type='GenericEdge' JOIN anchors d ON d.id=ce.src AND d.arch_type='District' WHERE a.arch_type='History' AND a.kind='NodeAnchor';